    private static final class SymbolDrawable extends Drawable {
        private final Path symbol;
        private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);

        SymbolDrawable(String pathData, int color) {
            Path parsed = PathParser.createPathFromPathData(pathData);
            symbol = parsed == null ? new Path() : parsed;
            paint.setColor(color);
            paint.setStyle(Paint.Style.FILL);
        }

        @Override public void draw(@NonNull Canvas canvas) {
            android.graphics.Rect bounds = getBounds();
            int save = canvas.save();
            canvas.translate(bounds.left, bounds.bottom);
            canvas.scale(bounds.width() / 960f, bounds.height() / 960f);
            canvas.drawPath(symbol, paint);
            canvas.restoreToCount(save);
        }
        @Override public void setAlpha(int alpha) { paint.setAlpha(alpha); invalidateSelf(); }
        @Override public void setColorFilter(@Nullable ColorFilter filter) { paint.setColorFilter(filter); invalidateSelf(); }
        @Override public void setTint(int color) { paint.setColor(color); invalidateSelf(); }
        @Override public int getOpacity() { return PixelFormat.TRANSLUCENT; }
        @Override public int getIntrinsicWidth() { return 24; }
        @Override public int getIntrinsicHeight() { return 24; }
    }
